import {trackEvent} from "./analytics.js";
import {restoreAccountSession,loadChildrenForSession} from "./account-session.js";
import {createLearningReportService} from "./learning-report-service.js";
import {learningReportView} from "./learning-report-views.js";
import {createParentDashboardService} from "./parent-dashboard-service.js";
import {parentDashboardView} from "./parent-dashboard-views.js";
import {getRoute,navigate} from "./router.js";
const app=document.querySelector("#app"),reports=createLearningReportService(),dashboard=createParentDashboardService(),pageSize=5,selectedKey="poma_parent_report_child";
if(!document.querySelector('link[href="css/parent-dashboard.css"]')){const style=document.createElement("link");style.rel="stylesheet";style.href="css/parent-dashboard.css";document.head.append(style);}
const initial=()=>({children:[],childId:null,reportType:"weekly",rows:[],deliveries:[],weeklyEmailEnabled:true,monthlyEmailEnabled:true,hasMore:false,loading:false,error:""});let state=initial(),renderToken=0;
const reset=()=>{state=initial();renderToken++;};function render(){app.innerHTML=learningReportView({selectedChildId:state.childId,...state});app.focus();}
async function loadReports({append=false}={}){const token=++renderToken;state.loading=true;state.error="";render();try{const offset=append?state.rows.length:0,[page,deliveries,weeklyEmailEnabled,monthlyEmailEnabled]=await Promise.all([reports.listReportPage(state.reportType,state.childId,offset,pageSize),reports.listDeliveryStatuses(state.reportType),reports.getWeeklyPreference(),reports.getMonthlyPreference()]);if(token!==renderToken)return;state.rows=append?[...state.rows,...page.rows]:page.rows;Object.assign(state,{deliveries,weeklyEmailEnabled,monthlyEmailEnabled,hasMore:page.hasMore});trackEvent("parent_report_opened",{period_type:state.reportType,source:"parent",has_data:Boolean(state.rows.length)});}catch{if(token!==renderToken)return;state.error="Raporlar şu anda yüklenemedi. Lütfen yeniden deneyin.";}finally{if(token===renderToken){state.loading=false;render();}}}
async function openReportCenter(){const account=await restoreAccountSession().catch(()=>({status:"signed-out"}));if(account.status!=="signed-in")return navigate("login");if(!["parent","both"].includes(account.profile?.account_type)){app.innerHTML=`<section class="card"><h1>Gelişim raporları yalnız veli hesaplarına açıktır.</h1><button class="button secondary" data-route="home">Ana sayfa</button></section>`;return;}const children=(await loadChildrenForSession(account).catch(()=>[])).filter(row=>row.is_active!==false),saved=sessionStorage.getItem(selectedKey);state.children=children;state.childId=children.some(row=>String(row.id)===saved)?saved:children[0]?.id||null;if(!state.childId){state.error="Rapor gösterilecek bağlı aktif çocuk profili bulunamadı.";render();return;}sessionStorage.setItem(selectedKey,String(state.childId));await loadReports();}
let dashboardBusy=false,dashboardAccount=null,dashboardChildren=[];
async function openParentDashboard(forcedChildId=null){if(getRoute()!=="parent"||dashboardBusy)return;dashboardBusy=true;try{dashboardAccount=await restoreAccountSession().catch(()=>null);if(dashboardAccount?.status!=="signed-in"||!["parent","both"].includes(dashboardAccount.profile?.account_type))return;dashboardChildren=(await loadChildrenForSession(dashboardAccount).catch(()=>[])).filter(row=>row.is_active!==false);const saved=forcedChildId||sessionStorage.getItem(selectedKey),childId=dashboardChildren.some(row=>String(row.id)===String(saved))?String(saved):dashboardChildren[0]?.id||null;if(childId)sessionStorage.setItem(selectedKey,String(childId));app.innerHTML=parentDashboardView({displayName:dashboardAccount.profile?.display_name,children:dashboardChildren,childId,loading:true});if(!childId){app.innerHTML=parentDashboardView({displayName:dashboardAccount.profile?.display_name,children:dashboardChildren,childId});return;}const data=await dashboard.load(dashboardAccount.user.id,childId);if(getRoute()==="parent")app.innerHTML=parentDashboardView({displayName:dashboardAccount.profile?.display_name,children:dashboardChildren,childId,data});}finally{dashboardBusy=false;}}
document.addEventListener("click",async event=>{if(getRoute()==="parent"){const route=event.target.closest("[data-parent-dashboard] [data-route]")?.dataset.route;if(route)navigate(route);return;}if(getRoute()!=="parent/reports")return;const tab=event.target.closest("[data-report-type]");if(tab){state.reportType=tab.dataset.reportType;state.rows=[];await loadReports();return;}if(event.target.closest("[data-load-more-reports]")){await loadReports({append:true});return;}if(event.target.closest("[data-action='print-learning-report']"))print();});
document.addEventListener("change",async event=>{if(getRoute()==="parent"&&event.target.matches("[data-parent-dashboard-child]")){sessionStorage.setItem(selectedKey,event.target.value);await openParentDashboard(event.target.value);return;}if(getRoute()!=="parent/reports")return;if(event.target.matches("[data-report-child]")){state.childId=event.target.value;sessionStorage.setItem(selectedKey,String(state.childId));state.rows=[];await loadReports();return;}if(event.target.matches("[data-weekly-email-preference]")){try{state.weeklyEmailEnabled=await reports.setWeeklyPreference(event.target.checked);render();}catch{state.error="E-posta tercihi kaydedilemedi.";render();}}if(event.target.matches("[data-monthly-email-preference]")){try{state.monthlyEmailEnabled=await reports.setMonthlyPreference(event.target.checked);render();}catch{state.error="E-posta tercihi kaydedilemedi.";render();}}});
window.addEventListener("hashchange",()=>queueMicrotask(()=>{if(getRoute()==="parent/reports")openReportCenter();else if(getRoute()==="parent")openParentDashboard();else reset();}));new MutationObserver(()=>{if(getRoute()==="parent"&&app.querySelector("[data-parent-report]")&&!app.querySelector("[data-parent-dashboard]"))openParentDashboard();}).observe(app,{childList:true});setTimeout(()=>{if(getRoute()==="parent/reports")openReportCenter();else if(getRoute()==="parent")openParentDashboard();},0);
